# -*- coding: utf-8 -*-
"""Simulacro final 4TC-17 · preguntas 1 a 25."""

P1 = [
 dict(nivel='basic', tema='Estructura de la PGN',
  ctx='Durante la inducción, un servidor recién posesionado pregunta de quién depende la División de Gestión Humana. Un compañero responde que del Despacho del Procurador General, «porque él firma los actos de personal»; otra sostiene que es una entidad adscrita con personería jurídica y presupuesto propio. El facilitador pide resolver el punto con el Decreto Ley 262 de 2000 a la vista, porque de ahí depende por qué línea sube una consulta y ante quién responde la División por sus trámites.',
  q='¿Cuál es la ubicación correcta de la División de Gestión Humana en la estructura de la entidad?',
  ops=['Es una entidad descentralizada adscrita a la Procuraduría, con personería jurídica y presupuesto propios, que define de manera autónoma la política de talento humano de la entidad.',
       'Depende directamente del Despacho del Procurador General, en el mismo nivel de las procuradurías delegadas, y recibe de él sus instrucciones sin intermediación de ninguna otra dependencia.',
       'Es una división del nivel central que depende de la Secretaría General, junto con la División Administrativa y la División Financiera, conforme al numeral 1.6.1 del artículo 2.',
       'Es una oficina del nivel territorial encargada de administrar el personal de las procuradurías regionales y provinciales, con autonomía frente a las dependencias del nivel central.'],
  correcta=2,
  expl=['Incorrecto: no tiene personería jurídica ni presupuesto propios; es una dependencia interna de la entidad.',
        'Incorrecto: esa es la posición de la Dirección Nacional de Investigaciones Especiales (art. 10), no la de la División de Gestión Humana.',
        'Correcto: el artículo 2 la ubica en el numeral 1.6.1, bajo la Secretaría General (1.6), con la Administrativa (1.6.2) y la Financiera (1.6.3).',
        'Incorrecto: es una división del nivel central; lo que hace frente al territorio es supervisar (art. 63, núm. 11).'],
  ref='Decreto Ley 262 de 2000, art. 2, núm. 1.6.1', refT='Estructura orgánica de la PGN'),

 dict(nivel='intermediate', tema='Competencias de la División y la Secretaría General',
  ctx='Dos servidores radican el mismo día una solicitud de permiso para estudiar: uno pide dos horas diarias y el otro, tres horas diarias. Ambos traen el visto bueno de su jefe inmediato y los dos cursos empiezan la semana entrante. Un compañero le dice que los dos permisos los concede la División de Gestión Humana, «porque los permisos de estudio son de Gestión Humana y punto»; otro sostiene que ambos los debe reconocer la Secretaría General, «porque toda licencia y todo permiso son de allá». Usted debe proyectar lo que corresponda.',
  q='Conforme a los artículos 62 y 63 del Decreto Ley 262 de 2000, ¿cómo se reparte la competencia?',
  ops=['Los dos los concede la División de Gestión Humana, porque el artículo 63 le asigna los permisos de estudio sin distinguir cuántas horas diarias solicite el servidor interesado.',
       'El de dos horas lo concede la División de Gestión Humana y el de tres lo reconoce la Secretaría General: la frontera está en que el permiso no supere las dos horas diarias.',
       'Los dos los reconoce la Secretaría General, porque el artículo 62 le atribuye vacaciones, licencias, comisiones y permisos, y la División solo prepara los proyectos para su firma.',
       'Ninguno puede concederse solo con el visto bueno del jefe inmediato: ambos requieren además el concepto previo de la Oficina de Planeación sobre el impacto en el servicio.'],
  correcta=1,
  expl=['Incorrecto: el numeral 6 del artículo 63 sí distingue, y el límite son dos horas diarias.',
        'Correcto: hasta dos horas diarias, la División (art. 63, núm. 6); más de dos horas, junto con vacaciones, licencias y comisiones, la Secretaría General (art. 62, núm. 6).',
        'Incorrecto: la Secretaría General conoce de los permisos que superan las dos horas, no de todos.',
        'Incorrecto: la norma no prevé ese concepto previo de Planeación.'],
  ref='Decreto Ley 262 de 2000, arts. 62 núm. 6 y 63 núm. 6', refT='Reparto de competencias en permisos'),

 dict(nivel='intermediate', tema='Verificación de requisitos y posesión',
  ctx='Llega el expediente de una persona nombrada en un empleo del nivel técnico del nivel central. El jefe de la dependencia donde va a trabajar llama insistiendo en que la posesión se surta mañana, porque el puesto lleva meses vacío. Al revisar los soportes usted encuentra que el certificado de experiencia de los últimos dos años no precisa las funciones desempeñadas, de modo que no es posible establecer si la experiencia es relacionada. El jefe dice que «eso se completa después» y que la persona ya renunció a su empleo anterior.',
  q='¿Cuál es la actuación que corresponde al Técnico en Criminalística 4TC-17?',
  ops=['Consignar por escrito qué acredita cada soporte y cuál requisito no quedó acreditado, requerir la certificación que precise las funciones e informar al competente, dejando constancia.',
       'Emitir el concepto favorable y surtir la posesión mañana, dejando una nota en la historia laboral que advierta que el certificado de experiencia se completará en los días siguientes.',
       'Devolver el expediente a la dependencia solicitante sin emitir concepto alguno, porque mientras el soporte no venga completo no hay actuación posible que la División deba adelantar.',
       'Emitir el concepto favorable porque la persona ya renunció a su empleo anterior, y negarle la posesión le causaría un perjuicio que la entidad tendría que reparar después.'],
  correcta=0,
  expl=['Correcto: el numeral 7 del artículo 63 encarga verificar los requisitos y emitir concepto escrito previo a la posesión; un certificado sin funciones no acredita experiencia relacionada.',
        'Incorrecto: posesionar con el requisito sin acreditar expone el nombramiento a nulidad, y la nota no sanea nada.',
        'Incorrecto: devolver sin concepto deja a la dependencia sin saber qué falta exactamente.',
        'Incorrecto: el perjuicio de quien renunció anticipadamente no habilita a declarar cumplido lo que no está acreditado.'],
  ref='Decreto Ley 262 de 2000, art. 63 núm. 7', refT='Concepto previo a la posesión'),

 dict(nivel='basic', tema='Carrera especial de la PGN',
  ctx='Un aspirante llega muy molesto al punto de atención y anuncia que demandará la Convocatoria 285-2026 «porque no la expidió la Comisión Nacional del Servicio Civil, como manda la Constitución». Dice que un abogado le aseguró que todo concurso del Estado debe ser administrado por la CNSC y que, por tanto, el de la Procuraduría es irregular desde su origen. Pide que la entidad le confirme el error por escrito y pregunta ante quién debe reclamar si no se lo confirman.',
  q='¿Cuál es la orientación correcta que debe darle?',
  ops=['Confirmarle que la convocatoria debió expedirla la CNSC y orientarlo para que presente allí su reclamación, porque es el organismo que administra y vigila las carreras del país.',
       'Explicarle que la Constitución no regula los concursos de los órganos de control y que esa materia depende por completo de lo que cada entidad reglamente de manera interna.',
       'Explicarle que el artículo 130 excluye de la CNSC las carreras de carácter especial y que el 279 ordena que la ley regule el concurso en el Ministerio Público, radicar lo que presente y dejar constancia.',
       'Negarse a dar orientación por tratarse de un asunto jurídico y remitirlo a la oficina jurídica para que allí le expliquen el fundamento normativo de la convocatoria en curso.'],
  correcta=2,
  expl=['Incorrecto: confirmar un error inexistente compromete a la entidad y desorienta al aspirante.',
        'Incorrecto: la Constitución sí se ocupa del punto, en los artículos 125, 130 y 279.',
        'Correcto: el art. 130 exceptúa las carreras especiales y el art. 279 remite a la ley, que son los Decretos Ley 262, 263 y 264 de 2000.',
        'Incorrecto: negarse a orientar en algo que sí puede explicarse incumple el deber de atención.'],
  ref='Constitución Política, arts. 130 y 279', refT='Fundamento de la carrera especial'),

 dict(nivel='advanced', tema='Derecho de petición: prórroga',
  ctx='Una petición compleja fue radicada el día 2. Al estudiarla, usted advierte que para responderla de fondo hay que pedir información a dos dependencias y revisar un expediente que está en el archivo central, que informó que solo podrá consultarse la semana entrante. Faltan cuatro días para el vencimiento. Un compañero le dice que lo mejor es enviar antes del vencimiento un oficio diciendo que «la solicitud se encuentra en trámite» y responder de fondo cuando se tenga todo listo.',
  q='¿Cuál es la actuación correcta frente al vencimiento del término?',
  ops=['Enviar el oficio informando que la solicitud se encuentra en trámite, porque así se da respuesta dentro del término y la de fondo puede remitirse cuando se complete la información.',
       'Responder dentro del término con la información disponible, aunque sea parcial, advirtiendo que lo faltante se complementará después, de modo que la respuesta quede rendida a tiempo.',
       'Dejar vencer el término y responder de fondo cuando se tenga todo, porque una respuesta completa protege mejor a la entidad que una respuesta apresurada e incompleta.',
       'Informar al peticionario, antes del vencimiento, la imposibilidad de responder en el término, con los motivos y el plazo en que se responderá, sin exceder el que la norma permite.'],
  correcta=3,
  expl=['Incorrecto: un «está en trámite» no resuelve nada ni interrumpe el término.',
        'Incorrecto: una respuesta parcial que promete completarse después no es respuesta de fondo.',
        'Incorrecto: dejar vencer el término es, simplemente, incumplir.',
        'Correcto: el CPACA exige informar antes del vencimiento los motivos y el plazo en que se responderá.'],
  ref='Ley 1437 de 2011, art. 14 (mod. Ley 1755 de 2015)', refT='Prórroga del término de respuesta'),

 dict(nivel='intermediate', tema='Falta de competencia y remisión',
  ctx='Se radica en la División una petición en la que una persona reclama por una actuación contractual que corresponde a otra dependencia de la entidad. Un compañero propone devolverla al peticionario indicándole a dónde debe dirigirse; otro propone archivarla porque «aquí no es». El escrito es claro en lo que pide, solo que lo pide a quien no puede resolverlo. El término ya empezó a correr desde la radicación y el peticionario dejó dirección física y correo electrónico.',
  q='¿Cuál es la actuación correcta?',
  ops=['Remitirla a la dependencia competente dentro del término previsto e informar de ello al peticionario, dejando constancia de la remisión y de la comunicación enviada.',
       'Devolverla al peticionario con una nota que le indique cuál es la dependencia competente, para que la presente directamente allí y el trámite comience ante quien debe resolverlo.',
       'Archivarla dejando constancia de que la División carece de competencia, porque continuar un trámite para el que no se es competente vicia la actuación desde su mismo inicio.',
       'Responderla desde la División con la información que pueda obtenerse de la otra dependencia, porque el peticionario tiene derecho a una respuesta de quien recibió su escrito.'],
  correcta=0,
  expl=['Correcto: la falta de competencia se resuelve remitiendo al competente dentro del término e informando al peticionario.',
        'Incorrecto: devolver traslada al peticionario una carga de la entidad y puede costarle el término.',
        'Incorrecto: archivar deja la petición sin resolver y sin remitir.',
        'Incorrecto: responder un asunto ajeno produce una respuesta de quien no podía darla.'],
  ref='Ley 1437 de 2011, art. 21', refT='Remisión por falta de competencia'),

 dict(nivel='advanced', tema='Firmeza del acto administrativo',
  ctx='Un servidor fue notificado personalmente de un acto el día 10 y, al recibirlo, manifestó verbalmente que «no está de acuerdo y lo va a pelear». El día 14, un compañero le pregunta a usted si ya puede registrarse la novedad en el sistema y comunicarle a la dependencia que el asunto quedó resuelto, porque están esperando para reorganizar el trabajo de la semana entrante. No se ha radicado ningún recurso y el término para recurrir todavía no ha vencido.',
  q='¿Cuál es la actuación correcta?',
  ops=['Registrar la novedad, porque el servidor no presentó ningún recurso en los días transcurridos y una manifestación verbal no produce efecto jurídico alguno sobre el acto notificado.',
       'Registrar la novedad advirtiendo a la dependencia que podría revertirse, de modo que el trabajo se reorganice y, si llega un recurso, se deshaga después el registro efectuado.',
       'Entender que la manifestación verbal equivale a un recurso de reposición y suspender el trámite hasta que el servidor presente por escrito los argumentos de su inconformidad.',
       'Esperar a que venza el término para recurrir: mientras corra, el acto no está en firme; llevar el control del término e informar a la dependencia el estado real, sin ejecutar todavía.'],
  correcta=3,
  expl=['Incorrecto: el acto no está en firme mientras corra el término, aunque no se haya presentado recurso.',
        'Incorrecto: registrar «advirtiendo que puede revertirse» ya es ejecutar, con efectos reales sobre el servidor.',
        'Incorrecto: una manifestación verbal no es un recurso ni suspende nada.',
        'Correcto: lo que no está en firme no se ejecuta; el papel del técnico es controlar el término e informar el estado real.'],
  ref='Ley 1437 de 2011, art. 87', refT='Firmeza de los actos administrativos'),

 dict(nivel='intermediate', tema='Notificación por aviso',
  ctx='Se expide un acto que niega a una servidora el reconocimiento de una prima. Un compañero intenta notificarla personalmente, pero ella no se presenta pese a haber sido citada en debida forma. Pasados varios días, él le dice a usted que «ya se intentó, así que se entiende notificada» y propone registrar la decisión en el sistema y archivar el expediente. La servidora dejó en su solicitud una dirección física y un correo electrónico, pero no autorizó expresamente la notificación electrónica.',
  q='¿Cuál es la actuación correcta?',
  ops=['Dar por surtida la notificación y archivar, porque la citación se envió oportunamente y la inasistencia de la interesada no puede paralizar de manera indefinida la actuación.',
       'Proceder a la notificación por aviso a la dirección registrada, con copia íntegra del acto y la indicación de los recursos, y dejar constancia de su envío y de la fecha de entrega.',
       'Enviar el acto al correo electrónico que la servidora registró en su solicitud, porque señalarlo como dato de contacto equivale a aceptar que se le notifique por ese medio.',
       'Publicar el acto en la cartelera de la entidad durante cinco días hábiles, de modo que la publicidad supla la notificación personal que no fue posible realizar por causa de ella.'],
  correcta=1,
  expl=['Incorrecto: la inasistencia no equivale a notificación y el acto quedaría sin efectos frente a ella.',
        'Correcto: fallida la notificación personal procede la notificación por aviso, con copia íntegra e indicación de recursos.',
        'Incorrecto: la notificación electrónica exige autorización expresa, que aquí no se dio.',
        'Incorrecto: la cartelera no es el medio para notificar actos de contenido particular.'],
  ref='Ley 1437 de 2011, art. 69', refT='Notificación por aviso'),

 dict(nivel='basic', tema='Clasificación de los empleos',
  ctx='Durante la inducción, una persona recién posesionada pregunta por qué a ella le exigieron concurso y a un compañero suyo, nombrado la misma semana en un cargo del nivel directivo, no. Un servidor responde que «en los órganos de control todos los empleos son de carrera»; otro, que «como la PGN tiene régimen especial, allí nada es de carrera». El jefe le pide a usted precisar el punto con fundamento constitucional, porque esa información quedará en el material de inducción.',
  q='¿Cuál es la respuesta correcta sobre la clasificación de los empleos por su naturaleza?',
  ops=['Todos los empleos de la Procuraduría son de carrera, porque el artículo 125 establece la carrera como regla general y los órganos de control no tienen excepción alguna a ese mandato.',
       'Ningún empleo de la Procuraduría es de carrera, porque su régimen especial sustituye el sistema de carrera y permite proveer todos los cargos por designación directa del Procurador.',
       'La diferencia depende del nivel jerárquico: los niveles directivo y asesor nunca son de carrera y los niveles profesional, técnico y asistencial siempre lo son, sin excepción posible.',
       'La carrera es la regla general y la excepción son, entre otros, los empleos de libre nombramiento y remoción: la PGN tiene carrera especial, no ausencia de carrera.'],
  correcta=3,
  expl=['Incorrecto: el propio artículo 125 establece excepciones.',
        'Incorrecto: carrera especial significa normas propias, no ausencia de carrera.',
        'Incorrecto: la clasificación por naturaleza no coincide mecánicamente con la clasificación por nivel.',
        'Correcto: el art. 125 hace de la carrera la regla y exceptúa, entre otros, los empleos de libre nombramiento y remoción.'],
  ref='Constitución Política, arts. 125 y 279', refT='Naturaleza de los empleos'),

 dict(nivel='intermediate', tema='Prelación del encargo',
  ctx='Hay una vacante definitiva de un empleo de carrera y no existe lista de elegibles vigente para ese cargo. Un directivo le pide que proyecte «para hoy» el nombramiento en provisionalidad de una persona externa que él recomienda, y le dice que asume la responsabilidad de la decisión. En la planta hay dos empleados de carrera que cumplirían los requisitos del empleo y tienen calificación sobresaliente, y uno de ellos ya manifestó interés por escrito en ocupar el cargo.',
  q='¿Cómo debe encauzarse la provisión de esa vacante?',
  ops=['Verificar primero si procede el encargo de un empleado de carrera que cumpla los requisitos y tenga buena calificación, porque el encargo tiene prelación, y dejar constancia escrita de la verificación.',
       'Proyectar de una vez el nombramiento provisional de la persona recomendada, porque al no existir lista de elegibles la entidad recupera plena libertad para designar a quien considere idóneo.',
       'Negarse a tramitar cualquier provisión, porque sin lista de elegibles vigente la vacante solo puede proveerse cuando se convoque un nuevo concurso y debe permanecer desierta mientras tanto.',
       'Proyectar el encargo a favor del empleado que manifestó interés por escrito, porque esa manifestación expresa le otorga mejor derecho frente al otro empleado que no se pronunció.'],
  correcta=0,
  expl=['Correcto: el encargo tiene prelación, y la constancia escrita de la verificación es lo que después demuestra que el orden se respetó.',
        'Incorrecto: la ausencia de lista no devuelve libertad de designación.',
        'Incorrecto: dejar el empleo desierto tampoco es la salida.',
        'Incorrecto: haber manifestado interés no da mejor derecho; se comparan requisitos y calificación.'],
  ref='Ley 909 de 2004, art. 24; Decreto Ley 262 de 2000, art. 190', refT='Orden de provisión de los empleos'),

 dict(nivel='advanced', tema='Carrera especial: período de prueba y calificación',
  ctx='Una servidora superó su período de prueba el día 3 de este mes. Su jefe inmediato le comenta a usted, de paso, que la calificará «el mes entrante, cuando baje la carga», porque ahora está en el cierre de un informe. La servidora, que sabe que de esa calificación depende su inscripción en carrera, le pregunta si eso puede esperar. Usted revisa el expediente, confirma la fecha exacta en que terminó el período de prueba y verifica que no hubo ninguna novedad que lo interrumpiera.',
  q='¿Qué corresponde hacer?',
  ops=['Informar por escrito al jefe el término de quince días hábiles que fija el artículo 222, avisar al jefe de la División, dejar constancia y orientar a la servidora sobre el estado del trámite.',
       'Esperar a que el jefe disponga de tiempo, porque la calificación es una facultad del evaluador y la División no puede imponerle plazos que interfieran con sus prioridades de trabajo.',
       'Proyectar usted mismo una calificación provisional favorable para que la servidora no pierda su inscripción en carrera, y someterla a la firma del jefe cuando regrese del cierre.',
       'Indicarle a la servidora que presente un derecho de petición al jefe de su dependencia, porque es ella la interesada y la División no interviene entre evaluador y evaluado.'],
  correcta=0,
  expl=['Correcto: el art. 222 del Decreto Ley 262 fija quince días hábiles para calificar tras el período de prueba, y de ahí dependen sus derechos de carrera.',
        'Incorrecto: el término no depende de la carga de trabajo del evaluador.',
        'Incorrecto: proyectar la calificación por el evaluador es usurpar la evaluación.',
        'Incorrecto: controlar el término es administración del proceso, que sí corresponde a la División.'],
  ref='Decreto Ley 262 de 2000, arts. 218 y 222', refT='Período de prueba y calificación en la PGN'),

 dict(nivel='intermediate', tema='Factores de calificación en la PGN',
  ctx='En una reunión de inducción, un servidor pregunta cuáles son los factores con los que lo van a calificar en la Procuraduría. Un compañero responde que «son los mismos del acuerdo de la CNSC, que es la norma nacional»; otro dice que «cada jefe arma los suyos según lo que le interese del cargo». El servidor insiste en que necesita saberlo porque quiere prepararse, y el jefe de la División le pide a usted precisar el punto con fundamento normativo antes de que el ciclo comience.',
  q='¿Cuál es la respuesta correcta?',
  ops=['Los factores son los que fije el acuerdo vigente de la Comisión Nacional del Servicio Civil, porque es la norma que unifica la evaluación del desempeño de los servidores públicos del país.',
       'El artículo 225 del Decreto Ley 262 de 2000 fija cuatro factores —calidad, eficiencia o rendimiento, responsabilidad y organización del trabajo— y los instrumentos los adopta la Comisión de Carrera.',
       'Cada jefe inmediato define los factores aplicables a su equipo al concertar los compromisos, porque es quien conoce las funciones concretas y puede ajustar la evaluación al puesto de trabajo.',
       'Los factores los fija cada año el Procurador General mediante resolución, de modo que no hay factores permanentes y el servidor debe consultar la resolución vigente en cada ciclo anual.'],
  correcta=1,
  expl=['Incorrecto: la CNSC no administra la carrera de la PGN.',
        'Correcto: el art. 225 enumera los cuatro factores y el art. 223 deja los instrumentos en la Comisión de Carrera.',
        'Incorrecto: el jefe califica, pero no define los factores.',
        'Incorrecto: los instrumentos de calificación los adopta la Comisión de Carrera, no una resolución anual.'],
  ref='Decreto Ley 262 de 2000, arts. 223 y 225', refT='Factores de calificación'),

 dict(nivel='basic', tema='Situaciones administrativas',
  ctx='Dos servidores se acercan el mismo día a la División. El primero pide vacaciones para la próxima semana, porque ya cumplió el año de servicio y quiere descansar. El segundo pide una licencia no remunerada de dos meses para atender un asunto personal. Ambos afirman que «eso es un derecho» y que la entidad no puede negárselo, y piden que se proyecten los dos actos de una vez. El jefe le pide a usted que, antes de proyectar nada, precise el punto por escrito.',
  q='¿Qué distinción debe hacerse entre las dos solicitudes?',
  ops=['Ambas son un derecho del servidor y la entidad debe concederlas en los términos pedidos, de modo que lo único que cabe verificar es que los soportes estén completos y en regla.',
       'Las vacaciones son un derecho causado al cumplir el año, aunque su fecha se concierte según el servicio; la licencia no remunerada es potestativa y puede negarse motivadamente.',
       'Ninguna de las dos es un derecho: ambas dependen de la necesidad del servicio, de modo que la entidad puede negarlas sin necesidad de motivar la decisión en uno u otro caso.',
       'Las vacaciones son potestativas porque su disfrute depende del servicio, y la licencia no remunerada es un derecho porque durante ella el servidor no percibe salario alguno.'],
  correcta=1,
  expl=['Incorrecto: tratarlas igual es el error; tienen naturaleza distinta.',
        'Correcto: las vacaciones son un derecho causado; la licencia no remunerada es potestativa y se niega o concede con motivación.',
        'Incorrecto: las vacaciones sí son un derecho y toda negativa debe motivarse.',
        'Incorrecto: invierte la regla.'],
  ref='Decreto 1083 de 2015 y Decreto 648 de 2017', refT='Situaciones administrativas'),

 dict(nivel='intermediate', tema='Historia laboral y datos sensibles',
  ctx='Usted terminó de verificar los soportes de la historia laboral de una servidora: entre ellos hay incapacidades médicas y la hoja de vida completa. Un abogado se presenta en la División, se identifica, dice que representa «los intereses de la familia» de la servidora y pide consultar la carpeta. No exhibe poder ni autorización de la titular. Insiste en que la petición es urgente porque «hay términos corriendo» y pide que al menos se le cuente verbalmente qué contiene.',
  q='¿Cuál es la actuación correcta?',
  ops=['Permitirle consultar únicamente los documentos que usted elaboró, como la lista de verificación de requisitos, y no el resto de la carpeta, que sí contiene datos personales protegidos.',
       'Atender la solicitud verbalmente sin entregar documentos, porque describir el contenido no constituye entrega de información protegida y evita una queja por mala atención al usuario.',
       'No darle acceso ni describirle el contenido, orientarlo sobre el canal formal para elevar su solicitud ante el competente y dejar constancia de la solicitud recibida.',
       'Entregarle copia de los soportes que no sean médicos, ya que la protección cubre solo los datos sensibles de salud y los demás documentos de la historia laboral son información pública.'],
  correcta=2,
  expl=['Incorrecto: la protección cubre la carpeta completa, incluidos los documentos que usted elaboró.',
        'Incorrecto: describir el contenido es revelarlo.',
        'Correcto: sin poder ni autorización del titular no hay acceso; se orienta sobre el canal y se deja constancia.',
        'Incorrecto: la hoja de vida también es información personal, no pública.'],
  ref='Ley 1581 de 2012 y Ley 1712 de 2014, art. 18', refT='Protección de datos en la historia laboral'),

 dict(nivel='advanced', tema='Asignación básica y factores salariales',
  ctx='Un servidor recién posesionado en un empleo del nivel técnico se acerca a su puesto. Dice que tiene una maestría y diez años de experiencia, que en su empleo anterior ganaba más y que su jefe «ya le dijo que le iban a reconocer algo adicional» por su perfil. Le pide a usted que proyecte lo necesario para que su asignación básica quede por encima de la del grado, y menciona que otro compañero del mismo grado, según él, gana más que él.',
  q='¿Cuál es la respuesta correcta?',
  ops=['Proyectar el ajuste solicitado, porque el perfil y la experiencia del servidor justifican objetivamente una asignación superior y la entidad puede reconocerla mediante acto motivado.',
       'Verificar primero cuánto gana el compañero que menciona y, si efectivamente es más, igualar las dos asignaciones para no vulnerar el derecho a la igualdad entre servidores del mismo grado.',
       'Explicarle que la asignación básica es reglada: la fija el Gobierno Nacional por decreto según el empleo y el grado, no depende del perfil, y orientarlo si considera que hay un error.',
       'Explicarle que su única alternativa es renunciar y volver a concursar por un empleo de grado superior, porque la asignación de su empleo actual no admite revisión de ningún tipo.'],
  correcta=2,
  expl=['Incorrecto: reconocer una asignación superior a la del grado desconoce el decreto salarial.',
        'Incorrecto: consultar el dato de otro servidor no es la vía, y la diferencia puede explicarse por factores distintos de la asignación básica.',
        'Correcto: la asignación básica es reglada; lo que sí cabe es orientar si él cree que hay un error en lo liquidado.',
        'Incorrecto: cerrarle el canal de revisión es incorrecto.'],
  ref='Decreto salarial anual y Decreto 1083 de 2015', refT='Asignación básica reglada'),

 dict(nivel='intermediate', tema='Novedades de nómina',
  ctx='Una servidora radica el día 27 una incapacidad médica de ocho días, cuando la nómina del mes ya se cerró. Un compañero le dice que la registre con fecha del día 2 del mes siguiente «para que cuadre con el período»; otro, que la guarde sin radicar hasta el mes entrante. La servidora pregunta además si eso afecta su pago y quién asume los días. El documento trae el diagnóstico y el origen común de la incapacidad, y ella pide que nadie más se entere del motivo.',
  q='¿Cuál es la actuación correcta?',
  ops=['Registrar la incapacidad con la fecha del mes siguiente para que coincida con el período de nómina en que se aplicará, de modo que el sistema no la rechace por extemporánea.',
       'Radicarla con su fecha real, registrarla como novedad del período correspondiente, documentar que por el cierre se aplicará en el siguiente, informarle y manejar el diagnóstico con reserva.',
       'Guardar el documento sin radicarlo hasta el mes entrante y entregarlo entonces, para evitar que quede una novedad pendiente de aplicación en un período de nómina ya cerrado.',
       'Radicarla con su fecha real y aplicarla de inmediato reabriendo la nómina del mes, porque una incapacidad es una novedad de obligatoria aplicación en el período en que se presenta.'],
  correcta=1,
  expl=['Incorrecto: cambiar la fecha es falsear el registro del que dependen el conteo de días y quién los asume.',
        'Correcto: fecha real, registro, documentación del traslado por cierre, información a la servidora y reserva del dato de salud.',
        'Incorrecto: guardarla sin radicar la deja sin constancia de presentación.',
        'Incorrecto: reabrir una nómina cerrada no está en sus manos.'],
  ref='Ley 100 de 1993 y Ley 1581 de 2012', refT='Novedades e incapacidades'),

 dict(nivel='basic', tema='Atención al usuario',
  ctx='En el punto de atención, una persona mayor pide ayuda para presentar una solicitud. Un compañero le dice que debe traerla escrita a máquina, en el formato de la entidad y con copia de su cédula autenticada, y que mientras tanto no puede radicarse nada. La persona dice que no sabe escribir bien y que vive a tres horas de la ciudad. Otro compañero sugiere que se devuelva y que vuelva otro día con alguien que la ayude a redactar el documento.',
  q='¿Cuál es la actuación correcta?',
  ops=['Recibir la petición, incluso verbal, apoyarla para dejarla por escrito si es necesario, radicarla con su fecha y entregarle constancia, sin exigir formatos ni autenticaciones que la ley no pide.',
       'Entregarle el formato de la entidad y explicarle que debe traerlo diligenciado, porque la uniformidad de los documentos permite tramitar las peticiones de manera ordenada y oportuna.',
       'Recibir la petición pero advertirle por escrito que no se tramitará hasta que aporte copia autenticada de su documento de identidad, requisito necesario para saber quién está solicitando.',
       'Remitirla a la oficina jurídica para que allí la asistan en la redacción, porque la División no tiene entre sus funciones ayudar a los ciudadanos a formular sus solicitudes por escrito.'],
  correcta=0,
  expl=['Correcto: el CPACA admite peticiones verbales y prohíbe exigir requisitos no previstos; el deber incluye facilitar.',
        'Incorrecto: exigir un formato propio es una de las prohibiciones del código.',
        'Incorrecto: exigir autenticación es otro requisito no previsto.',
        'Incorrecto: trasladarla a otra oficina desatiende un deber propio.'],
  ref='Ley 1437 de 2011, arts. 5, 7 y 15', refT='Derechos y deberes ante las autoridades'),

 dict(nivel='advanced', tema='Límite del rol: firma del acto',
  ctx='El jefe de la División le encarga preparar el acto de retiro por pensión de un servidor. Usted proyecta el documento con todos sus soportes: la resolución de reconocimiento de la pensión, la verificación del tiempo de servicio y la liquidación preliminar. Al terminar, su compañero le dice que lo firme usted mismo, «porque el jefe está en comisión toda la semana y el servidor necesita el acto para su trámite ante el fondo». El servidor, en efecto, está presionando a diario.',
  q='¿Qué corresponde hacer?',
  ops=['Firmar el acto en ausencia del jefe y dejar constancia de que lo hizo por razones de urgencia, de modo que el servidor pueda adelantar su trámite ante el fondo sin esperar al regreso.',
       'Dejar el proyecto listo con todos sus soportes, remitirlo por el canal para la firma del competente, informar al servidor el estado real y los tiempos, y dejar constancia de la urgencia.',
       'Entregar al servidor una copia del proyecto sin firma, advirtiéndole que es un borrador, para que pueda ir adelantando su trámite ante el fondo mientras llega la firma del competente.',
       'Solicitar al jefe que autorice la firma por correo electrónico y, con esa autorización, suscribir el acto, porque la autorización escrita del superior suple su firma cuando hay urgencia.'],
  correcta=1,
  expl=['Incorrecto: firmar sin competencia vicia el acto, y la urgencia no lo sanea.',
        'Correcto: la División prepara los actos y los firma el Procurador General (art. 63, núm. 5).',
        'Incorrecto: entregar un borrador induce a error a quien lo reciba.',
        'Incorrecto: la competencia la asigna la norma, no el superior por correo.'],
  ref='Decreto Ley 262 de 2000, art. 63 núm. 5', refT='Proyectar frente a firmar'),

 dict(nivel='intermediate', tema='Gestión documental y TRD',
  ctx='Debe archivar la constancia de verificación y los soportes de un encargo ya surtido. Al consultar la Tabla de Retención Documental de la dependencia, encuentra que la serie que describe con más precisión ese tipo de documento no aparece de forma literal: hay dos series parecidas —historias laborales y actos administrativos de personal— y ninguna coincide exactamente con el caso. El término para dejar el archivo organizado vence el viernes y la persona encargada de archivo está incapacitada.',
  q='¿Cuál es la conducta que corresponde?',
  ops=['Archivar en la serie que más se parezca y anotar en la carpeta una nota explicando la duda, de modo que quien revise después pueda reclasificar el documento si lo considera necesario.',
       'Consultar por el canal institucional al responsable de gestión documental o a quien lo supla, dejar constancia escrita de la consulta y archivar conforme a la orientación recibida.',
       'Crear una carpeta nueva con el nombre del servidor y custodiarla aparte hasta que la encargada de archivo regrese, para no clasificar erróneamente un documento con valor probatorio.',
       'Archivar en la serie de mayor tiempo de retención, porque conservar más tiempo un documento nunca causa perjuicio y evita el riesgo de una eliminación anticipada del expediente.'],
  correcta=1,
  expl=['Incorrecto: elegir «la más parecida» es una decisión unilateral sobre un instrumento que no le corresponde modificar.',
        'Correcto: se consulta por el canal, se deja constancia de la consulta y se actúa conforme a la orientación.',
        'Incorrecto: una carpeta propia fuera del sistema es peor.',
        'Incorrecto: la retención no se elige por conveniencia.'],
  ref='Ley 594 de 2000 y la TRD de la dependencia', refT='Tablas de Retención Documental'),

 dict(nivel='advanced', tema='Objetividad: el hallazgo desfavorable',
  ctx='Le encargan verificar los soportes de experiencia de una persona nombrada antes de su posesión. El jefe que impulsa el nombramiento le había anticipado su lectura: que la experiencia «alcanza de sobra». Al revisar, usted encuentra una certificación que sí acredita dieciocho meses de experiencia relacionada, y otra —la que completaría el tiempo exigido— que corresponde a un contrato cuyo objeto no guarda relación con las funciones del empleo. El término vence mañana y el jefe insiste en que el asunto «está claro».',
  q='¿Cómo debe redactarse la constancia?',
  ops=['Consignar el soporte que sí acredita y mencionar el otro de manera general, para no desorientar al jefe con un dato que podría exigir una revisión adicional de la hoja de vida.',
       'Consignar solo el soporte que acredita y comentar verbalmente el otro al jefe, de modo que sea él quien decida si corresponde pedir una certificación complementaria al interesado.',
       'Consignar los dos soportes con el mismo nivel de detalle, describiendo qué acredita cada uno y qué requisito queda o no acreditado, sin concluir más de lo que los documentos respaldan.',
       'Pedir una ampliación del término para confirmar el segundo soporte antes de rendir la constancia, porque incluir un dato desfavorable sin confirmarlo podría afectar la claridad del trámite.'],
  correcta=2,
  expl=['Incorrecto: mencionar «de manera general» es filtrar un dato desfavorable.',
        'Incorrecto: comentarlo verbalmente lo deja fuera del documento que soporta la decisión.',
        'Correcto: el dato desfavorable se consigna con el mismo rigor que el favorable; decidir qué hacer con él es de otro.',
        'Incorrecto: aplazar la constancia para «confirmar» es otra forma de no consignarlo.'],
  ref='Manual de funciones, función 2; Decreto Ley 262 de 2000, art. 63 núm. 7', refT='Objetividad en la verificación'),

 dict(nivel='intermediate', tema='Conteo de términos',
  ctx='Una petición fue radicada el jueves 30 de abril a las 3 de la tarde, dentro del horario de atención. El viernes 1 de mayo es festivo. Un compañero le dice a usted que el término empieza el mismo jueves y que se cuentan días calendario; otro, que empieza el lunes porque el jueves «ya estaba muy avanzado». La peticionaria llama y pide una fecha exacta para saber cuándo puede insistir, y advierte que de esa fecha depende un trámite suyo ante otra entidad.',
  q='¿Cómo deben contarse los términos?',
  ops=['Desde el mismo jueves 30, en días calendario, descontando únicamente el festivo del 1 de mayo por tratarse de un día en que la entidad no presta atención al público ni tramita asuntos.',
       'Desde el lunes siguiente, en días hábiles, porque una radicación hecha en horas de la tarde se entiende presentada el primer día hábil siguiente al de su recepción material en la entidad.',
       'Desde el mismo jueves 30, en días hábiles, de modo que ese jueves cuenta como el primer día del término y el festivo del 1 de mayo simplemente no se computa dentro del plazo.',
       'Desde el día hábil siguiente a la radicación, en días hábiles, excluyendo sábados, domingos y festivos: el jueves 30 no cuenta y el 1 de mayo tampoco se computa.'],
  correcta=3,
  expl=['Incorrecto: los términos del CPACA se cuentan en días hábiles, no calendario.',
        'Incorrecto: la hora no desplaza la fecha de radicación.',
        'Incorrecto: el día de la radicación no cuenta.',
        'Correcto: se cuenta en días hábiles, a partir del día hábil siguiente, excluyendo sábados, domingos y festivos.'],
  ref='Ley 1437 de 2011 y Código de Régimen Político y Municipal, art. 62', refT='Conteo de términos'),

 dict(nivel='basic', tema='Ministerio Público',
  ctx='En una reunión, alguien sostiene que la Procuraduría «hace parte de la rama ejecutiva porque cumple funciones administrativas» y otro, que «es una rama más del poder público». Un tercero pregunta entonces quién integra el Ministerio Público, porque cree que es solo la PGN y sus procuradurías territoriales. El jefe le pide a usted precisar los dos puntos con fundamento constitucional, porque la información quedará en un documento de inducción.',
  q='¿Cuál es la precisión correcta?',
  ops=['La Procuraduría es parte de la rama ejecutiva porque ejerce función administrativa, y el Ministerio Público está integrado exclusivamente por la Procuraduría General y sus dependencias.',
       'La Procuraduría es un órgano autónomo e independiente (art. 113) y el Ministerio Público lo ejercen el Procurador, el Defensor del Pueblo, los procuradores delegados y los personeros (art. 118).',
       'La Procuraduría es una cuarta rama del poder público, con el mismo rango que la legislativa, la ejecutiva y la judicial, y el Ministerio Público lo integran la Procuraduría y la Contraloría.',
       'La Procuraduría pertenece a la rama judicial porque ejerce el poder disciplinario, y el Ministerio Público lo conforman la Procuraduría y la Defensoría bajo dirección del Consejo Superior.'],
  correcta=1,
  expl=['Incorrecto: ejercer función administrativa no la ubica en la rama ejecutiva.',
        'Correcto: el art. 113 la reconoce como órgano autónomo y el art. 118 enumera quiénes ejercen el Ministerio Público.',
        'Incorrecto: no es una cuarta rama y la Contraloría no integra el Ministerio Público.',
        'Incorrecto: no pertenece a la rama judicial.'],
  ref='Constitución Política, arts. 113, 117 y 118', refT='Órganos autónomos y Ministerio Público'),

 dict(nivel='advanced', tema='Competencia y validez del acto',
  ctx='Un acto de personal fue firmado por el jefe de la División cuando, según los artículos 62 y 63 del Decreto Ley 262 de 2000, el asunto correspondía a la Secretaría General. El acto ya fue notificado y el servidor empezó a disfrutar de lo reconocido. Un compañero propone no decir nada «porque el beneficio ya se dio y nadie se ha quejado». Al revisar, usted confirma que la situación se repite en otros dos expedientes del mismo mes, firmados por la misma persona.',
  q='¿Cuál es la actuación correcta?',
  ops=['No decir nada, porque el acto produjo efectos favorables al servidor y removerlo ahora le causaría un perjuicio que la entidad tendría que reparar de todos modos más adelante.',
       'Proyectar de inmediato un acto que revoque los tres y expedirlos nuevamente con la firma correcta, sin comunicar nada a los servidores para no generar una alarma innecesaria.',
       'Documentar el hallazgo con precisión, informarlo por el canal al competente —incluidos los otros dos casos— y abstenerse de decidir por su cuenta cómo se corrige la situación.',
       'Pedir a la Secretaría General que firme ahora los mismos actos con la fecha original, de modo que el expediente quede completo y el defecto de competencia desaparezca del trámite.'],
  correcta=2,
  expl=['Incorrecto: callar deja tres actos viciados produciendo efectos.',
        'Incorrecto: revocar por cuenta propia y sin comunicar desconoce los derechos de los afectados.',
        'Correcto: la falta de competencia es el vicio más grave; se documenta, se informa y decide el competente.',
        'Incorrecto: hacer firmar con fecha original es antedatar: convierte un vicio en una falsedad.'],
  ref='Ley 1437 de 2011, art. 137; Decreto Ley 262 de 2000, arts. 62 y 63', refT='Competencia como elemento de validez'),

 dict(nivel='intermediate', tema='Concepto frente a acto administrativo',
  ctx='Un jefe de dependencia le envía por correo una consulta escrita: quiere saber si puede encargar en un empleo del nivel técnico a una servidora que no acredita uno de los requisitos del manual. Usted estudia el caso y concluye que no procede. Un compañero le sugiere que redacte la respuesta como un acto administrativo «para que quede claro que no se puede». El jefe, por su parte, dice que si la respuesta es favorable procederá con el encargo de una vez.',
  q='¿Qué documento corresponde y qué debe advertirse?',
  ops=['Un acto administrativo con parte resolutiva, porque la respuesta define si el encargo procede y esa definición produce efectos jurídicos sobre la servidora involucrada en el asunto.',
       'Un acto administrativo pero sin indicación de recursos, porque la consulta la formuló un jefe de dependencia y no la persona directamente interesada en el resultado del trámite.',
       'Un concepto, que orienta y no obliga ni compromete la responsabilidad de quien lo emite, advirtiendo que un concepto favorable no habilita por sí solo a surtir el encargo.',
       'Una comunicación informal por el mismo correo, porque las consultas entre dependencias de la misma entidad no requieren documento formal ni quedan sujetas a términos de respuesta.'],
  correcta=2,
  expl=['Incorrecto: darle forma de acto crea la apariencia de una decisión que nadie adoptó.',
        'Incorrecto: un acto sin indicación de recursos sería además irregular.',
        'Correcto: lo que se pide es una opinión: es una consulta, se responde con concepto y debe advertirse su alcance.',
        'Incorrecto: una consulta escrita es una petición con su propio término.'],
  ref='Ley 1437 de 2011, art. 28', refT='Alcance de los conceptos'),

 dict(nivel='advanced', tema='Base de aportes y error detectado',
  ctx='Al revisar la base de aportes de un servidor, usted advierte que durante varios meses se incluyó en ella un concepto que, según la norma, no constituye factor salarial. Un compañero le dice que lo deje así «porque cotizar de más no perjudica a nadie y hasta le conviene al servidor para su pensión»; otro, que lo corrija de inmediato sin informar a nadie para que no se note. La diferencia acumulada es significativa y los aportes ya fueron girados a las administradoras.',
  q='¿Cuál es la actuación correcta?',
  ops=['Dejar la base como está, porque una cotización superior a la debida beneficia al servidor en su pensión futura y no causa perjuicio ni a la entidad ni al sistema de seguridad social.',
       'Corregir la base de inmediato en la nómina siguiente, sin informar, para que la diferencia deje de acumularse y el asunto no genere alarma en el equipo ni en el servidor afectado.',
       'Documentar el hallazgo con precisión, informarlo por el canal al competente y abstenerse de corregir por decisión propia, porque la corrección afecta aportes ya pagados y al servidor.',
       'Consultar al servidor si prefiere que se corrija o que se mantenga la base actual, y actuar conforme a lo que responda, dejando constancia escrita de su manifestación de voluntad.'],
  correcta=2,
  expl=['Incorrecto: cotizar de más es un pago sin causa con recursos públicos.',
        'Incorrecto: corregir en silencio borra el rastro de un error que alguien debe conocer.',
        'Correcto: se documenta y se informa; el competente decide cómo se corrige y con qué efectos.',
        'Incorrecto: la base de aportes la fija la norma, no la preferencia del servidor.'],
  ref='Ley 100 de 1993 y Decreto 1083 de 2015', refT='Factores salariales y base de aportes'),
]
